DO $$ DECLARE f record; BEGIN FOR f IN SELECT p.oid::regprocedure AS signature,p.proname,p.prorettype FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prosecdef LOOP EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM PUBLIC, anon',f.signature); IF f.prorettype='trigger'::regtype OR f.proname IN ('claim_phone_setup_code','support_claim_call_ai','support_finish_call_ai') THEN EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM authenticated',f.signature); ELSE EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated',f.signature); END IF; EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',f.signature); END LOOP; END $$;